import{_ as l,h as i,i as e,c as n,v as o,p as d,x as r,m as s,e as m,S as h}from"./chunks/framework.Dvtg8yj2.js";const k=JSON.parse('{"title":"显存占用分解","description":"","frontmatter":{"title":"显存占用分解","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/memory-breakdown.md","filePath":"llm/memory-breakdown.md","lastUpdated":1788454257000}'),p={name:"llm/memory-breakdown.md"};function c(A,a,V,E,B,_){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="显存占用分解" tabindex="-1">显存占用分解 <a class="header-anchor" href="#显存占用分解" aria-label="Permalink to &quot;显存占用分解&quot;">​</a></h1><div class="epigraph"><p>一张加速卡上的字节不是一锅粥：权重相对固定，KV 随并发与长度涨，激活在前填时冒尖，碎片让「还剩好几 GB」的同时接不进下一条请求。</p><footer>—— 对照自回归服务中权重、KV 缓存、激活与分配器碎片的账单拆分</footer></div><p>显存打满是生成服务最常见的硬墙之一，但「打满」需要拆开看。模型参数、优化器状态（训练才有）、KV 缓存、前填激活、CUDA 上下文与工作区、以及分配器碎片，占用的原因和治理手段都不同。把 OOM 一律归因于「模型太大」，会错过分页 KV、减并发、切前填块、或换 GQA 这些便宜得多的杠杆。本篇给推理服务一张分解账单；带宽意义上的墙见 <a href="/llm/decode-memory-wall">decode 显存墙</a>，分页如何消灭预留空洞见 <a href="/llm/paged-attention">PagedAttention</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>推理稳态下，一块 GPU 的 HBM 大致被五类对象切开。权重：\\(P\\) 个参数乘每参数字节（FP16 为 2，INT8 为 1，FP8 类似）。KV：每条请求、每层、每个 KV 头、每个已写入位置，键与值各一份。激活：前填时与序列长度、层宽、批内 token 数成正比，解码时激活很小。运行时：驱动、NCCL、cuBLAS workspace、torch CUDA 上下文，常是数 GB 级常数。碎片：逻辑占用低于水位，却没有形状合适的空闲块。</p><p>产品看到的症状混在一起：并发上不去、上下文长度加一点就炸、前填某条长提示时尖刺 OOM、或「nvidia-smi 显示还有空」但分配失败。不分解，就不知道该量化权重、该压缩 KV、该限制前填 token 预算，还是该换分页分配器。训练侧还要把 Adam 动量、梯度、检查点激活算进去；本篇范围是服务。</p><h3 id="权重是地板-kv-是可变项" tabindex="-1">权重是地板，KV 是可变项 <a class="header-anchor" href="#权重是地板-kv-是可变项" aria-label="Permalink to &quot;权重是地板，KV 是可变项&quot;">​</a></h3><p>权重在加载后几乎不变（LoRA 多适配器是例外，见多 LoRA 服务）。它决定最低卡型：70B 的 FP16 约 140 GB，必须切多卡或量化。KV 才是并发与长度的函数。粗算一条请求一层的字节：</p> \\[\\mathrm{KV}(n)\\approx 2\\cdot L\\cdot n\\cdot h_{\\mathrm{kv}}\\cdot d_k\\cdot b, \\]<p>因子 2 为 K 与 V，\\(L\\) 层数，\\(n\\) 当前上下文，\\(b\\) 元素宽度。\\(h_{\\mathrm{kv}}\\) 在 MHA 等于查询头，GQA / MQA / MLA 把它打下来。系统总 KV 是运行集上 \\(\\sum_r \\mathrm{KV}(n_r)\\) 再加页内浪费。并发 16、每条 8k、大模型未压缩时，KV 可以超过权重，成为一等公民。还按「模型文件多大」去买卡，会在长上下文上突然破产。</p><p><span class="marginnote">查询头数不进 KV 公式。把 \\(h_q\\) 代入会把容量需求高估 \\(h_q/h_{\\mathrm{kv}}\\) 倍。规划并发与窗口时，必须以 KV 头为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建议在引擎里暴露四条水位，而不是一个 <code>memory_allocated</code>。权重（及常驻量化表）、KV 池（已用页 / 已分配页）、激活峰值（按最近前填）、运行时保留。OOM 时打哪一条涨，决定动作：权重量化或切并行；KV 则减最大并发、减窗口、KV 量化、驱逐或拒绝；激活则切 <a href="/llm/chunked-prefill">chunked prefill</a> 或减前填批；运行时则查是否重复初始化上下文、是否 workspace 过大。</p><p>分页把 KV 从「按 max_seq_len 预留」改成「按实际 token 买页」。逻辑占用接近 \\(\\sum n_r\\)，内部碎片约半页 × 请求数 × 层 × 头结构。页太大，内部浪费明显；页太小，页表与核间接开销涨。未分页时外部碎片会让水位看起来还低就分配失败——这是账单上必须单列「不可用空闲」的原因。</p><h3 id="前填激活与解码的不对称" tabindex="-1">前填激活与解码的不对称 <a class="header-anchor" href="#前填激活与解码的不对称" aria-label="Permalink to &quot;前填激活与解码的不对称&quot;">​</a></h3><p>前填要对 \\(n\\) 个位置保留注意力与 FFN 的中间张量（即使 FlashAttention 不物化 \\(n\\times n\\) 分数，FFN 激活仍随 \\(n\\) 线性、宽随 \\(d\\)）。一条 100k 提示的激活尖刺可以短暂超过 KV 池里所有短聊天之和，把本已安全的水位打穿。解码步的激活与批大小成正比、与 \\(n\\) 弱相关，通常不是容量主角，带宽才是。因此「能 decode 128k」的配置，仍可能在「prefill 128k」上 OOM——两条路径要分别压测。</p>',16)),(e(),d(h,null,{default:r(()=>[m(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20HBM%5B%22HBM%20%E6%80%BB%E9%87%8F%22%5D%20--%3E%20W%5B%22%E6%9D%83%E9%87%8D%20%2F%20%E9%87%8F%E5%8C%96%E8%A1%A8%22%5D%0A%20%20HBM%20--%3E%20KV%5B%22KV%20%E9%A1%B5%E6%B1%A0%22%5D%0A%20%20HBM%20--%3E%20ACT%5B%22%E5%89%8D%E5%A1%AB%E6%BF%80%E6%B4%BB%E5%B0%96%E5%88%BA%22%5D%0A%20%20HBM%20--%3E%20RT%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E4%B8%8E%20workspace%22%5D%0A%20%20HBM%20--%3E%20FR%5B%22%E7%A2%8E%E7%89%87%E4%B8%8E%E4%B8%8D%E5%8F%AF%E7%94%A8%E7%A9%BA%E9%97%B2%22%5D%0A%20%20KV%20--%3E%20CONC%5B%22%E5%B9%B6%E5%8F%91%20%C3%97%20%E9%95%BF%E5%BA%A6%20%C3%97%20h_kv%22%5D%0A%20%20ACT%20--%3E%20N%5B%22%E6%8F%90%E7%A4%BA%20token%20%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容量墙与带宽墙同源不同证。容量：上述各项之和超过物理 HBM（再扣保留）。带宽：每步要搬的权重加 KV 超过总线，TPOT 变差，但 <code>smi</code> 显示还没满。压缩 KV 同时缓解两者；加并发在容量允许时改善权重摊销（吞吐升），同时增加 KV 字节（更接近容量墙）并增加每步要扫的 KV（带宽更紧）。这是同一旋钮的三面，不能只看占用百分比。</p><h3 id="切并行不一定切-kv-池" tabindex="-1">切并行不一定切 KV 池 <a class="header-anchor" href="#切并行不一定切-kv-池" aria-label="Permalink to &quot;切并行不一定切 KV 池&quot;">​</a></h3><p>张量并行把权重按列/行切开，每卡权重下降，但 KV 是否切开取决于实现：有的每卡存全量 KV（浪费容量换通信形状），有的沿头或序列切。规划多卡时必须读清 KV 复制因子，否则「切 8 卡」并不给出 8 倍 KV 池。流水线并行每卡只持有部分层的 KV，容量按层分摊，但气泡与调度是另一笔账。</p><p><span class="marginnote">碎片不只来自 KV。PyTorch 缓存分配器持有已释放但未归还驱动的块，会出现「业务以为释放了、smi 仍高」。服务进程应在稳态看 <code>reserved</code> 与 <code>allocated</code> 之差；差值长期膨胀要查缓存与碎片，而不是再买卡。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>量化权重减地板，可能伤质量；量化 KV 减可变项，可能伤长程检索（针测会先红）。驱逐与滑窗减 \\(n\\) 的有效部分，任务若要精确中间事实，会与 <a href="/llm/niah">NIAH</a> 冲突。这些是质量换容量，必须配对评测，不能只报「能上 32 并发」。</p><p>多 LoRA、多模态视觉塔、投机草稿模型，都是额外常驻权重。账单要加行，否则主模型看着能进，加上适配器就 OOM。CPU 卸载权重或 KV 把容量墙挪到 PCIe：占用问题变成延迟问题，TTFT / ITL 报表会说话。</p><p>不要用训练时的「激活检查点省显存」直接套解码服务。解码没有长反向图；前填的激活策略与训练时的重算不同。把训练的 memory profiler 截图拿来估 vLLM 实例，数量级会对不上。</p><p><span class="marginnote">nvidia-smi 是进程级粗表，含驱动上下文，不含逻辑 KV 页数。容量治理应以引擎内部计数为准，smi 只做对账。两者差很多时，先查泄漏与碎片，再查公式。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>服务显存应拆成权重、KV、前填激活、运行时、碎片；OOM 要对号入座再动手。</li><li>权重是地板；KV 随 \\(L,n,h_{\\mathrm{kv}},b\\) 与并发线性涨，长上下文下可超过权重。</li><li>分页消灭外部预留空洞，仍留内部半页浪费；未分页时「有空闲」也能分配失败。</li><li>前填激活尖刺与解码容量要分开压测；能 decode 的长度未必能一次 prefill。</li><li>切并行时核对 KV 复制因子；量化与驱逐是质量换容量。</li><li>用引擎水位对账，而不是只用 smi。</li><li>出处：对照 PagedAttention / vLLM 的 KV 池模型与自回归服务的权重–缓存–激活分解；带宽侧见 decode 显存墙。</li></ul>',12))])}const u=l(p,[["render",c]]);export{k as __pageData,u as default};
